using System.Net;using System.Net.Http.Headers;using System.Net.Http.Json;using System.Text.Json;
using ForensicEdu.Domain.Entities;using ForensicEdu.Domain.Enums;using ForensicEdu.Infrastructure.Persistence;using ForensicEdu.Infrastructure.Services;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;
static class StudentPaymentsScenario
{
 public static async Task Seed(IServiceProvider services,bool preview=false){using var scope=services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();var student=(await db.Users.FindAsync("student"))!;student.Nombres="Alumno";student.Apellidos="de prueba";student.FullName="Alumno de prueba";
 db.Courses.Add(new Course{Id="payments-course",Title="Balística Forense",Price=100,ShortCode="BAL"});db.Users.Add(new User{Id="other-student",Email="other@example.invalid",FullName="Otro alumno"});
 Add(db,"foreign","other-student",PaymentStatus.APROBADO);
 if(preview){Add(db,"own-pending","student",PaymentStatus.PENDIENTE);Add(db,"own-approved","student",PaymentStatus.APROBADO);}
 await db.SaveChangesAsync();}
 private static void Add(ApplicationDbContext db,string id,string owner,PaymentStatus status){var order=new Order{Id="order-"+id,OrderCode="ORD-PRUEBA-"+id.ToUpperInvariant(),UserId=owner,ProductId="payments-course",ProductType=ProductType.CURSO,ProductTitle="Balística Forense",Amount=100,Price=100,Status=status==PaymentStatus.APROBADO?OrderStatus.APROBADO:OrderStatus.PENDIENTE_VALIDACION};db.Orders.Add(order);db.PaymentEvidences.Add(new PaymentEvidence{Id="payment-"+id,OrderId=order.Id,Status=status,Amount=100,BankName="BCP",OperationNumber="PRUEBA-"+id.ToUpperInvariant(),AccountHolderName="ALUMNO DE PRUEBA",OperationDate=DateTime.UtcNow.Date,RegisteredAt=DateTime.UtcNow.AddHours(status==PaymentStatus.APROBADO?-24:-1),VoucherFileUrl="fixture-private-voucher"});}
 public static async Task Run(HttpClient http,IServiceProvider services,TokenService tokens){await Seed(services);var count=0;void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("OK: "+label);}
 Check((await http.GetAsync("/api/student/payments")).StatusCode==HttpStatusCode.Unauthorized,"Historial de pagos requiere sesión");
 http.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",tokens.Create(new User{Id="student",Role=UserRole.ESTUDIANTE}));
 var empty=await http.GetFromJsonAsync<JsonElement>("/api/student/payments");Check(empty.GetProperty("total").GetInt32()==0,"Alumno no recibe pagos de otra cuenta");
 var checkout=await http.PostAsJsonAsync("/api/orders/checkout",new{userId="student",productId="payments-course",productType=1,amount=100,bankName="BCP",operationNumber="MY-PAYMENT-001",operationDate=DateTime.UtcNow.AddMinutes(-5),accountHolderName="Alumno de prueba"});Check(checkout.IsSuccessStatusCode,"Compra de un curso registra orden y pago mediante checkout");var order=(await checkout.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("orderId").GetString()!;
 var list=await http.GetFromJsonAsync<JsonElement>("/api/student/payments?page=1&pageSize=1");var row=list.GetProperty("items")[0];Check(list.GetProperty("total").GetInt32()==1&&row.GetProperty("orderId").GetString()==order,"Pago de la compra aparece en el historial paginado");
 Check(row.GetProperty("userId").GetString()=="student"&&row.GetProperty("productTitle").GetString()=="Balística Forense"&&row.GetProperty("amount").GetDecimal()==100&&row.GetProperty("operationNumber").GetString()=="MY-PAYMENT-001","Respuesta incluye propietario, curso, monto y operación para Mis Pagos");Check(row.GetProperty("status").GetInt32()==1&&!row.GetProperty("hasVoucher").GetBoolean(),"Pago pendiente se muestra antes de la aprobación o del comprobante");
 using(var scope=services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();var payment=await db.PaymentEvidences.SingleAsync(p=>p.OrderId==order);payment.Status=PaymentStatus.APROBADO;payment.VoucherFileUrl="private-proof";payment.ReviewedAt=DateTime.UtcNow;await db.SaveChangesAsync();}
 var updated=await http.GetFromJsonAsync<JsonElement>("/api/student/payments");var approved=updated.GetProperty("items")[0];Check(approved.GetProperty("status").GetInt32()==3&&approved.GetProperty("hasVoucher").GetBoolean(),"Actualizar historial recupera revisión y comprobante sin duplicar registros");Check(!updated.GetRawText().Contains("private-proof")&&!updated.GetRawText().Contains("foreign"),"Historial no expone rutas privadas ni pagos ajenos");
 Console.WriteLine($"{count} comprobaciones de Mis Pagos superadas; sin PostgreSQL remoto ni operaciones reales.");
 }
}
